Rect2i TileMap::get_used_rect() const
{
	// Return the visible rect of the tilemap.
	bool first = true;
	Rect2i rect = Rect2i();
	for (const TileMapLayer* layer : layers) {
		Rect2i layer_rect = layer->get_used_rect();
		if (layer_rect == Rect2i()) {
			continue;
		}
		if (first) {
			rect = layer_rect;
			first = false;
		}
		else {
			rect = rect.merge(layer_rect);
		}
	}
	return rect;
}

