{
	orientation = p_orientation;
	if (orientation == HORIZONTAL) {
		set_v_size_flags(0);
	}
	else {
		set_h_size_flags(0);
	}

	if (focus_by_default) {
		set_focus_mode(FOCUS_ALL);
	}
	else {
		set_focus_mode(FOCUS_ACCESSIBILITY);
	}
	set_step(0);
}

