Control* TabContainer::get_tab_control(int p_idx) const
{
	if (p_idx < 0) {
		return nullptr;
	}
	ERR_THREAD_GUARD_V(nullptr);

	for (Node* child : iterate_children()) {
		Control* control = _as_tab_control(child);
		if (!control) {
			continue;
		}

		if (p_idx > 0) {
			p_idx--;
		}
		else {
			return control;
		}
	}
	return nullptr;
}

