bool Node3D::is_visible_in_tree() const
{
	ERR_READ_THREAD_GUARD_V(
		false); // Since visibility can only be changed from main thread, this is safe to call.
	const Node3D* s = this;

	while (s) {
		if (!s->data.visible) {
			return false;
		}
		s = s->data.parent;
	}

	return true;
}

