void Area3D::_notification(int p_what) {
	collision_state.handle_notification(this, p_what);
	switch (p_what) {
		case NOTIFICATION_ENTER_TREE: {
			_initialize_wind();
		} break;
		case NOTIFICATION_EXIT_TREE:
		case NOTIFICATION_DISABLED: {
			_clear_monitoring();
		} break;
	}
}

