{
	render_instance.fti_update_servers_xform(this);
}

VoxelGI::VoxelGI()
{
	voxel_gi = Renderer::voxel_gi_create();
	set_disable_scale(true);
}

VoxelGI::~VoxelGI()
{
	ERR_FAIL_NULL(Renderer::data);
	Renderer::free_rid(voxel_gi);
}

