	JoltArea3D* area = area_owner.get_or_null(p_area);
	ERR_FAIL_NULL(area);

	JoltShape3D* shape = shape_owner.get_or_null(p_shape);
	ERR_FAIL_NULL(shape);

	area->set_shape(p_shape_idx, shape);
