{
	RWLockRead read_lock(iteration_rwlock);
	return iteration;
}

NavLink3D::NavLink3D() : sync_dirty_request_list_element(this)
{
	iteration.instantiate();
}

NavLink3D::~NavLink3D()
{
	cancel_sync_request();

	iteration = Ref<NavIteration3D>();
}


